class Customer extends DataClass implements Insertable<Customer> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String name;
  final String? phone;
  final String? email;
  final String? cardNumber;
  final DateTime? birthday;
  final String? note;
  final double discountPercent;
  final int bonusBalance;

  /// Positive = customer owes the store.
  final int debtBalance;
  final int debtLimit;
  final int totalSpent;
  final int visits;
  final DateTime? lastVisitAt;
  final String? tags;
  const Customer({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.name,
    this.phone,
    this.email,
    this.cardNumber,
    this.birthday,
    this.note,
    required this.discountPercent,
    required this.bonusBalance,
    required this.debtBalance,
    required this.debtLimit,
    required this.totalSpent,
    required this.visits,
    this.lastVisitAt,
    this.tags,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || cardNumber != null) {
      map['card_number'] = Variable<String>(cardNumber);
    }
    if (!nullToAbsent || birthday != null) {
      map['birthday'] = Variable<DateTime>(birthday);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    map['discount_percent'] = Variable<double>(discountPercent);
    map['bonus_balance'] = Variable<int>(bonusBalance);
    map['debt_balance'] = Variable<int>(debtBalance);
    map['debt_limit'] = Variable<int>(debtLimit);
    map['total_spent'] = Variable<int>(totalSpent);
    map['visits'] = Variable<int>(visits);
    if (!nullToAbsent || lastVisitAt != null) {
      map['last_visit_at'] = Variable<DateTime>(lastVisitAt);
    }
    if (!nullToAbsent || tags != null) {
      map['tags'] = Variable<String>(tags);
    }
    return map;
  }

  CustomersCompanion toCompanion(bool nullToAbsent) {
    return CustomersCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      name: Value(name),
      phone: phone == null && nullToAbsent
          ? const Value.absent()
          : Value(phone),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      cardNumber: cardNumber == null && nullToAbsent
          ? const Value.absent()
          : Value(cardNumber),
      birthday: birthday == null && nullToAbsent
          ? const Value.absent()
          : Value(birthday),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      discountPercent: Value(discountPercent),
      bonusBalance: Value(bonusBalance),
      debtBalance: Value(debtBalance),
      debtLimit: Value(debtLimit),
      totalSpent: Value(totalSpent),
      visits: Value(visits),
      lastVisitAt: lastVisitAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastVisitAt),
      tags: tags == null && nullToAbsent ? const Value.absent() : Value(tags),
    );
  }

  factory Customer.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Customer(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      name: serializer.fromJson<String>(json['name']),
      phone: serializer.fromJson<String?>(json['phone']),
      email: serializer.fromJson<String?>(json['email']),
      cardNumber: serializer.fromJson<String?>(json['cardNumber']),
      birthday: serializer.fromJson<DateTime?>(json['birthday']),
      note: serializer.fromJson<String?>(json['note']),
      discountPercent: serializer.fromJson<double>(json['discountPercent']),
      bonusBalance: serializer.fromJson<int>(json['bonusBalance']),
      debtBalance: serializer.fromJson<int>(json['debtBalance']),
      debtLimit: serializer.fromJson<int>(json['debtLimit']),
      totalSpent: serializer.fromJson<int>(json['totalSpent']),
      visits: serializer.fromJson<int>(json['visits']),
      lastVisitAt: serializer.fromJson<DateTime?>(json['lastVisitAt']),
      tags: serializer.fromJson<String?>(json['tags']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
      'name': serializer.toJson<String>(name),
      'phone': serializer.toJson<String?>(phone),
      'email': serializer.toJson<String?>(email),
      'cardNumber': serializer.toJson<String?>(cardNumber),
      'birthday': serializer.toJson<DateTime?>(birthday),
      'note': serializer.toJson<String?>(note),
      'discountPercent': serializer.toJson<double>(discountPercent),
      'bonusBalance': serializer.toJson<int>(bonusBalance),
      'debtBalance': serializer.toJson<int>(debtBalance),
      'debtLimit': serializer.toJson<int>(debtLimit),
      'totalSpent': serializer.toJson<int>(totalSpent),
      'visits': serializer.toJson<int>(visits),
      'lastVisitAt': serializer.toJson<DateTime?>(lastVisitAt),
      'tags': serializer.toJson<String?>(tags),
    };
  }

  Customer copyWith({
    String? id,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<DateTime?> deletedAt = const Value.absent(),
    String? name,
    Value<String?> phone = const Value.absent(),
    Value<String?> email = const Value.absent(),
    Value<String?> cardNumber = const Value.absent(),
    Value<DateTime?> birthday = const Value.absent(),
    Value<String?> note = const Value.absent(),
    double? discountPercent,
    int? bonusBalance,
    int? debtBalance,
    int? debtLimit,
    int? totalSpent,
    int? visits,
    Value<DateTime?> lastVisitAt = const Value.absent(),
    Value<String?> tags = const Value.absent(),
  }) => Customer(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
    name: name ?? this.name,
    phone: phone.present ? phone.value : this.phone,
    email: email.present ? email.value : this.email,
    cardNumber: cardNumber.present ? cardNumber.value : this.cardNumber,
    birthday: birthday.present ? birthday.value : this.birthday,
    note: note.present ? note.value : this.note,
    discountPercent: discountPercent ?? this.discountPercent,
    bonusBalance: bonusBalance ?? this.bonusBalance,
    debtBalance: debtBalance ?? this.debtBalance,
    debtLimit: debtLimit ?? this.debtLimit,
    totalSpent: totalSpent ?? this.totalSpent,
    visits: visits ?? this.visits,
    lastVisitAt: lastVisitAt.present ? lastVisitAt.value : this.lastVisitAt,
    tags: tags.present ? tags.value : this.tags,
  );
  Customer copyWithCompanion(CustomersCompanion data) {
    return Customer(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
      name: data.name.present ? data.name.value : this.name,
      phone: data.phone.present ? data.phone.value : this.phone,
      email: data.email.present ? data.email.value : this.email,
      cardNumber: data.cardNumber.present
          ? data.cardNumber.value
          : this.cardNumber,
      birthday: data.birthday.present ? data.birthday.value : this.birthday,
      note: data.note.present ? data.note.value : this.note,
      discountPercent: data.discountPercent.present
          ? data.discountPercent.value
          : this.discountPercent,
      bonusBalance: data.bonusBalance.present
          ? data.bonusBalance.value
          : this.bonusBalance,
      debtBalance: data.debtBalance.present
          ? data.debtBalance.value
          : this.debtBalance,
      debtLimit: data.debtLimit.present ? data.debtLimit.value : this.debtLimit,
      totalSpent: data.totalSpent.present
          ? data.totalSpent.value
          : this.totalSpent,
      visits: data.visits.present ? data.visits.value : this.visits,
      lastVisitAt: data.lastVisitAt.present
          ? data.lastVisitAt.value
          : this.lastVisitAt,
      tags: data.tags.present ? data.tags.value : this.tags,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Customer(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('name: $name, ')
          ..write('phone: $phone, ')
          ..write('email: $email, ')
          ..write('cardNumber: $cardNumber, ')
          ..write('birthday: $birthday, ')
          ..write('note: $note, ')
          ..write('discountPercent: $discountPercent, ')
          ..write('bonusBalance: $bonusBalance, ')
          ..write('debtBalance: $debtBalance, ')
          ..write('debtLimit: $debtLimit, ')
          ..write('totalSpent: $totalSpent, ')
          ..write('visits: $visits, ')
          ..write('lastVisitAt: $lastVisitAt, ')
          ..write('tags: $tags')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    createdAt,
    updatedAt,
    deletedAt,
    name,
    phone,
    email,
    cardNumber,
    birthday,
    note,
